import { Component } from 'react';
import About from './About';
import Portfolio from './Portfolio';
import './App.css';

class App extends Component {
  state = { page: 'About' }; // default section

  setPage = (page) => this.setState({ page });

  renderPage() {
    const { page } = this.state;
    if (page === 'About') return <About />;
    if (page === 'Portfolio') return <Portfolio />;
    return null;
  }

  render() {
    const { page } = this.state;

    return (
      <div className="personal-profile-app">
        <header className="header-navigation">
          <nav>
            <ul className="navigation-menu">
              <li>
                <button
                  className={page === 'About' ? 'active' : ''}
                  onClick={() => this.setPage('About')}
                >
                  About
                </button>
              </li>
              <li>
                <button
                  className={page === 'Portfolio' ? 'active' : ''}
                  onClick={() => this.setPage('Portfolio')}
                >
                  Portfolio
                </button>
              </li>
            </ul>
          </nav>
        </header>

        <main className="main-content-area">{this.renderPage()}</main>
      </div>
    );
  }
}

export default App;
